Write the coordinates of $A$, $B$, $C$ and $D$.
[tikz]
\begin{tikzpicture}[x=6mm,y=6mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\draw[color=black!20,very thin,xstep=6mm,ystep=6mm] (-4,-4) grid (4,4);
\draw[<->,black] (-4.5,0)--(4.5,0) node[right] {$x$};
\draw[<->,black] (0,-4.5)--(0,4.5) node[above] {$y$};
\foreach \n in {-4,-3,-2,-1,1,2,3,4}{\draw[black] (\n,-0.08)--(\n,0.08);\draw[black] (-0.08,\n)--(0.08,\n);\path (\n,0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\n$};\path (0,\n) node[left,font=\fontsize{8.5}{10}\selectfont] {$\n$};}
