\fill[black] (2,2) circle (1.5pt);
\fill[black] (-2,1) circle (1.5pt);
\fill[black] (-1,-3) circle (1.5pt);
\fill[black] (2.5,-1.5) circle (1.5pt);
\path (2,2) node[above right] {$A$};
\path (-2,1) node[above left] {$B$};
\path (-1,-3) node[below left] {$C$};
\path (2.5,-1.5) node[below right] {$D$};
\end{tikzpicture}
[/tikz]

